import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_json_file(file_path):
    """Load JSON file and return its content."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, FileNotFoundError):
        return None

def extract_facts_from_fda(packet_dir, recall_number, fact_names):
    """
    Extract facts for a given recall number from FDA enforcement reports.
    Returns dict with fact_name -> list of (value, document) pairs.
    """
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    data = load_json_file(file_path)
    if not data or "results" not in data:
        return {}

    facts = {name: [] for name in fact_names}

    for record in data["results"]:
        if record.get("recall_number") == recall_number:
            doc_name = "fda_enforcement_reports"

            # Map fact names to field names
            field_map = {
                "initiation date": "recall_initiation_date",
                "classification date": "center_classification_date",
                "termination date": "termination_date"
            }

            for fact_name in fact_names:
                field = field_map.get(fact_name)
                if field and field in record:
                    value = record[field]
                    if value:  # Only add if value exists
                        facts[fact_name].append((value, doc_name))

    return facts

def process_pair(packet_dir, rule_id, entity, facts_needed):
    """
    Process a single rule_id::entity pair.
    Returns dict mapping fact names to appropriate values.
    """
    result = {}

    # Extract all needed facts for this entity
    all_facts = extract_facts_from_fda(packet_dir, entity, facts_needed)

    for fact_name in facts_needed:
        values = all_facts.get(fact_name, [])

        if not values:
            result[fact_name] = "ABSENT"
        else:
            # Check for conflicts
            unique_values = set(val for val, _ in values)
            if len(unique_values) > 1:
                result[fact_name] = "CONFLICT"
            else:
                # Format date if it's a date field
                value_str = values[0][0]
                doc_name = values[0][1]

                # Parse and reformat date if it's a valid date string
                parsed_date = parse_date(value_str)
                if parsed_date:
                    value_str = parsed_date.strftime("%Y-%m-%d")

                result[fact_name] = [value_str, doc_name]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_config = manifest["facts"]

    # Process all pairs
    output = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts_needed = facts_config.get(rule_id, [])

        result = process_pair(packet_dir, rule_id, entity, facts_needed)
        output[pair] = result

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

