import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to YYYY-MM-DD."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        # Remove any leading/trailing whitespace
        date_str = date_str.strip()
        # Handle empty strings
        if not date_str:
            return None
        # Parse as YYYYMMDD
        dt = datetime.strptime(date_str, "%Y%m%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        # If parsing fails, return None
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Create a mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number")
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name):
    """Extract fact value from record based on fact name."""
    if fact_name == "initiation date":
        return record.get("recall_initiation_date")
    elif fact_name == "classification date":
        return record.get("center_classification_date")
    elif fact_name == "termination date":
        return record.get("termination_date")
    else:
        return None

def process_pair(pair, records, facts_map):
    """Process a single pair (rule_id::entity)."""
    rule_id, entity = pair.split("::", 1)
    facts = facts_map[rule_id]

    result = {}

    # Find record for this entity
    record = records.get(entity)

    for fact_name in facts:
        if not record:
            result[fact_name] = "ABSENT"
        else:
            raw_value = extract_fact_value(record, fact_name)
            if raw_value is None or raw_value == "":
                result[fact_name] = "ABSENT"
            else:
                # Parse and format the date
                formatted_value = parse_date(raw_value)
                if formatted_value:
                    result[fact_name] = [formatted_value, "fda_enforcement_reports"]
                else:
                    result[fact_name] = "ABSENT"

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load FDA data
    records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        output[pair] = process_pair(pair, records, manifest["facts"])

    # Print JSON result
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

