import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date from YYYYMMDD string, return datetime.date or None if empty/invalid."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)
    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number")
        if recall_num:
            records[recall_num] = record
    return records

def compute_fact_value(record, fact_name, rule_id):
    """Compute the value for a fact based on the rule and record."""
    if rule_id == "fda.classified_30d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            date = parse_date(date_str)
            return [date.strftime("%Y-%m-%d"), "fda_enforcement_reports"] if date else "ABSENT"
        elif fact_name == "classification date":
            date_str = record.get("center_classification_date", "")
            date = parse_date(date_str)
            return [date.strftime("%Y-%m-%d"), "fda_enforcement_reports"] if date else "ABSENT"
    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            date = parse_date(date_str)
            return [date.strftime("%Y-%m-%d"), "fda_enforcement_reports"] if date else "ABSENT"
        elif fact_name == "termination date":
            date_str = record.get("termination_date", "")
            date = parse_date(date_str)
            return [date.strftime("%Y-%m-%d"), "fda_enforcement_reports"] if date else "ABSENT"
    return "ABSENT"

def main(packet_dir, manifest_path):
    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load data
    fda_records = load_fda_data(packet_dir)

    # Prepare output
    output = {}

    # Process each pair
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)

        # Find record(s) for this entity (recall number)
        # In this dataset, entity is the recall number
        record = fda_records.get(entity)

        if not record:
            # If no record found, all facts are ABSENT
            fact_values = {fact: "ABSENT" for fact in manifest["facts"][rule_id]}
        else:
            fact_values = {}
            for fact in manifest["facts"][rule_id]:
                fact_values[fact] = compute_fact_value(record, fact, rule_id)

        output[pair] = fact_values

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    main(sys.argv[1], sys.argv[2])

