            return json.load(f)
    except (json.JSONDecodeError, FileNotFoundError):
        return None

def extract_facts_from_fda(packet_dir, recall_number, fact_names):
    """
    Extract facts for a given recall number from FDA enforcement reports.
    Returns dict with fact_name -> (value, document) or "ABSENT" or "CONFLICT"
    """
    file_name = "fda_enforcement_reports.json"
    file_path = os.path.join(packet_dir, file_name)

    if not os.path.exists(file_path):
        return {fact: "ABSENT" for fact in fact_names}

    data = load_json_file(file_path)
    if not data or "results" not in data:
        return {fact: "ABSENT" for fact in fact_names}

    # Find all records matching the recall number
    matching_records = []
    for record in data["results"]:
        if record.get("recall_number") == recall_number:
            matching_records.append(record)

    if not matching_records:
        return {fact: "ABSENT" for fact in fact_names}

    # Map fact names to field names
    field_map = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }

    result = {}
    for fact_name in fact_names:
        field_name = field_map.get(fact_name)
        if not field_name:
            result[fact_name] = "ABSENT"
            continue

        # Collect all values for this field from matching records
        values = []
        for record in matching_records:
            value = record.get(field_name, "")
            if value:
                values.append(value)

        if not values:
            result[fact_name] = "ABSENT"
        elif len(set(values)) > 1:
            result[fact_name] = "CONFLICT"
        else:
            # Single value found - format date if it's a date field
            raw_value = values[0]
            formatted_value = format_date_for_output(raw_value)
            if formatted_value:
                result[fact_name] = [formatted_value, "fda_enforcement_reports"]
            else:
                # If it's not a valid date, return the raw value
                result[fact_name] = [raw_value, "fda_enforcement_reports"]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts = manifest["facts"]

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts.get(rule_id, [])

        # Extract facts for this entity
        fact_values = extract_facts_from_fda(packet_dir, entity, fact_names)

        result[pair] = fact_values

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

