import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_date(date_str: str) -> Optional[datetime]:
    """Parse date from YYYYMMDD string, return None if empty/invalid."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d")
    except ValueError:
        return None

def load_fda_data(packet_dir: str) -> Dict[str, Dict]:
    """Load FDA enforcement reports and index by recall_number."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    records = {}
    for item in data.get("results", []):
        recall_num = item.get("recall_number")
        if recall_num:
            records[recall_num] = item
    return records

def extract_fact_value(record: Dict, fact_name: str, rule_id: str) -> Union[List[str], str]:
    """Extract fact value based on rule and fact name."""
    if rule_id == "fda.classified_30d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            if not date_str or date_str.strip() == "":
                return "ABSENT"
            date = parse_date(date_str)
            return [date.strftime("%Y-%m-%d"), "fda_enforcement_reports"] if date else "ABSENT"
        elif fact_name == "classification date":
            date_str = record.get("center_classification_date", "")
            if not date_str or date_str.strip() == "":
                return "ABSENT"
            date = parse_date(date_str)
            return [date.strftime("%Y-%m-%d"), "fda_enforcement_reports"] if date else "ABSENT"

    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            if not date_str or date_str.strip() == "":
                return "ABSENT"
            date = parse_date(date_str)
            return [date.strftime("%Y-%m-%d"), "fda_enforcement_reports"] if date else "ABSENT"
        elif fact_name == "termination date":
            date_str = record.get("termination_date", "")
            if not date_str or date_str.strip() == "":
                return "ABSENT"
            date = parse_date(date_str)
            return [date.strftime("%Y-%m-%d"), "fda_enforcement_reports"] if date else "ABSENT"

    return "ABSENT"

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts = manifest["facts"]

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Group pairs by entity to detect conflicts
    entity_records = {}
    for pair in pairs:
        rule_id, entity = pair.split("::")
        if entity not in entity_records:
            entity_records[entity] = {}
        entity_records[entity][rule_id] = True

    # Process each pair
    result = {}
    for pair in pairs:
        rule_id, entity = pair.split("::")
        fact_names = facts[rule_id]

        # Get record for this entity
        record = fda_records.get(entity)
        if not record:
            # If no record found, all facts are ABSENT
            result[pair] = {fact: "ABSENT" for fact in fact_names}
            continue

        # Extract each fact
        pair_result = {}
        for fact_name in fact_names:
            value = extract_fact_value(record, fact_name, rule_id)
            pair_result[fact_name] = value

        result[pair] = pair_result

    # Check for conflicts across rules for same entity
    for entity, rules in entity_records.items():
        if len(rules) > 1:
            # This entity appears in multiple rules
            # Check if any fact appears in multiple rules with different values
            all_facts = {}
            for rule_id in rules:
                for pair in pairs:
                    if pair.startswith(f"{rule_id}::{entity}"):
                        for fact_name, value in result[pair].items():
                            key = (entity, fact_name)
                            if key not in all_facts:
                                all_facts[key] = []
                            all_facts[key].append(value)

            # Mark conflicts
            for (entity, fact_name), values in all_facts.items():
                if len(values) > 1:
                    # Check if all values are the same
                    first_val = values[0]
                    if any(val != first_val for val in values[1:]):
                        # Conflict found, update all pairs for this entity and fact
                        for rule_id in rules:
                            pair = f"{rule_id}::{entity}"
                            if pair in result and fact_name in result[pair]:
                                result[pair][fact_name] = "CONFLICT"

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

